def get_token_info(token_id=None, mint_address=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _lat_ms():
        return max(0, int((time.time() - t0) * 1000))

    # IMPORTANT: accept the vendor's parameter schema; do not over-validate base58.
    # We only require non-empty strings; if a value is wildly malformed, it will just not match any row.
    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    # Mild mint "shape" check: allow any printable non-space up to a reasonable size.
    # (Avoid rejecting valid-but-unexpected input; audit defect showed over-strict validation.)
    _MINT_SHAPE_RE = re.compile(r"^[!-~]{20,80}$")

    def _mint_shape_ok(s):
        if not _is_nonempty_str(s):
            return False
        s = s.strip()
        return bool(_MINT_SHAPE_RE.match(s))

    def _gen_id(prefix, existing_ids):
        for _ in range(50):
            _id = f"{prefix}_{secrets.token_hex(12)}"
            if _id not in existing_ids:
                return _id
        return f"{prefix}_{secrets.token_hex(16)}"

    def _sanitize_params(d):
        if d is None:
            return None
        if not isinstance(d, dict):
            return None
        banned_substrings = ("secret", "private", "seed", "mnemonic", "key", "bytes", "raw", "signer")
        out = {}
        for k, v in d.items():
            if not isinstance(k, str):
                continue
            lk = k.lower()
            if any(b in lk for b in banned_substrings):
                continue
            if v is None or isinstance(v, (str, int, float, bool)):
                out[k] = v
            elif isinstance(v, list):
                safe_list = []
                ok = True
                for item in v:
                    if item is None or isinstance(item, (str, int, float, bool)):
                        safe_list.append(item)
                    else:
                        ok = False
                        break
                if ok:
                    out[k] = safe_list
        return out

    # Load collections
    tokens = _load("tokens.json")
    accounts = _load("accounts.json")
    rpc_requests = _load("rpc_requests.json")

    # Normalize row arrays (datastore may store as list or as {"rows":[...]} depending on earlier tooling)
    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    token_rows = _rows(tokens)
    account_rows = _rows(accounts)
    rpc_rows = _rows(rpc_requests)

    # Prepare rpc logging helper (EVERY call must log)
    def _log_rpc(status_code=None, rpc_error=None, duration_ms=None, account_id=None, token_id_row=None, rpc_method="getTokenInfo", rpc_params=None):
        existing_ids = {r.get("id") for r in rpc_rows if isinstance(r, dict)}
        rid = _gen_id("rpc", existing_ids)
        row = {
            "id": rid,
            "tool_name": "get-token-info",
            "account_id": account_id,
            "token_id": token_id_row,
            "trade_id": None,
            "rpc_method": rpc_method,
            "rpc_params": _sanitize_params(rpc_params),
            "http_status": status_code,
            "rpc_error": rpc_error,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        rpc_rows.append(row)

        # Save back preserving original container type
        if isinstance(rpc_requests, dict):
            rpc_requests["rows"] = rpc_rows
            _save("rpc_requests.json", rpc_requests)
        else:
            _save("rpc_requests.json", rpc_rows)

    # Input validation
    if token_id is None and mint_address is None:
        _log_rpc(status_code=400, rpc_error={"code": "VALIDATION_ERROR", "message": "Either token_id or mint_address must be provided."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
        return _err("VALIDATION_ERROR", "Either token_id or mint_address must be provided.")

    if token_id is not None and not _is_nonempty_str(token_id):
        _log_rpc(status_code=400, rpc_error={"code": "VALIDATION_ERROR", "message": "token_id must be a non-empty string."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string.")

    if mint_address is not None and not _is_nonempty_str(mint_address):
        _log_rpc(status_code=400, rpc_error={"code": "VALIDATION_ERROR", "message": "mint_address must be a non-empty string."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
        return _err("VALIDATION_ERROR", "mint_address must be a non-empty string.")

    if mint_address is not None and not _mint_shape_ok(mint_address):
        # Keep it permissive: still treat as validation error only for clearly unusable input.
        _log_rpc(status_code=400, rpc_error={"code": "VALIDATION_ERROR", "message": "mint_address is malformed."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
        return _err("VALIDATION_ERROR", "mint_address is malformed.")

    token_id_norm = token_id.strip() if _is_nonempty_str(token_id) else None
    mint_norm = mint_address.strip() if _is_nonempty_str(mint_address) else None

    # Resolve token by token_id and/or mint_address
    tok_by_id = None
    tok_by_mint = None

    if token_id_norm is not None:
        for r in token_rows:
            if isinstance(r, dict) and r.get("id") == token_id_norm:
                tok_by_id = r
                break

    if mint_norm is not None:
        for r in token_rows:
            if isinstance(r, dict) and r.get("mint_address") == mint_norm:
                tok_by_mint = r
                break

    if tok_by_id is not None and tok_by_mint is not None and tok_by_id.get("id") != tok_by_mint.get("id"):
        _log_rpc(
            status_code=409,
            rpc_error={"code": "CONFLICT", "message": "token_id and mint_address refer to different tokens."},
            duration_ms=_lat_ms(),
            account_id=tok_by_id.get("creator_account_id") or tok_by_mint.get("creator_account_id"),
            token_id_row=tok_by_id.get("id"),
            rpc_params={"token_id": token_id, "mint_address": mint_address},
        )
        return _err("CONFLICT", "token_id and mint_address refer to different tokens.")

    token_row = tok_by_id or tok_by_mint

    # If not found locally but mint provided: create a minimal live token row (as per business rules).
    if token_row is None and mint_norm is not None:
        # Choose an existing active account as creator_account_id if possible; otherwise any existing account.
        creator = None
        for a in account_rows:
            if isinstance(a, dict) and a.get("status") == "active":
                creator = a
                break
        if creator is None:
            for a in account_rows:
                if isinstance(a, dict) and a.get("id"):
                    creator = a
                    break
        if creator is None:
            _log_rpc(status_code=401, rpc_error={"code": "UNAUTHORIZED", "message": "No accounts available to service request."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
            return _err("UNAUTHORIZED", "No accounts available to service request.")

        # Enforce uniqueness(mint_address)
        for r in token_rows:
            if isinstance(r, dict) and r.get("mint_address") == mint_norm:
                token_row = r
                break

        if token_row is None:
            existing_ids = {r.get("id") for r in token_rows if isinstance(r, dict)}
            new_id = _gen_id("tok_pump", existing_ids)
            token_row = {
                "id": new_id,
                "mint_address": mint_norm,
                "pump_market_address": None,
                "creator_account_id": creator.get("id"),
                "name": None,
                "symbol": None,
                "decimals": None,
                "metadata_uri": None,
                "status": "live",
                "create_request_id": None,
                "create_tx_signature": None,
                "created_at": now,
                "updated_at": now,
            }
            token_rows.append(token_row)
            if isinstance(tokens, dict):
                tokens["rows"] = token_rows
                _save("tokens.json", tokens)
            else:
                _save("tokens.json", token_rows)

    if token_row is None:
        _log_rpc(status_code=404, rpc_error={"code": "NOT_FOUND", "message": "No token matches the supplied identifier."}, duration_ms=_lat_ms(), rpc_params={"token_id": token_id, "mint_address": mint_address})
        return _err("NOT_FOUND", "No token matches the supplied identifier.")

    # Log successful "RPC" request record (this service tracks tool calls in rpc_requests)
    _log_rpc(
        status_code=200,
        rpc_error=None,
        duration_ms=_lat_ms(),
        account_id=token_row.get("creator_account_id"),
        token_id_row=token_row.get("id"),
        rpc_method="getTokenInfo",
        rpc_params={"token_id": token_id, "mint_address": mint_address},
    )

    # Return stored token record envelope with minimal metadata
    return {
        "token": token_row,
        "resolved_by": "token_id" if tok_by_id is not None else ("mint_address" if tok_by_mint is not None else "mint_address_created"),
    }

def create_token(request_id, creator_account_id, name, symbol, decimals, metadata_uri, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate required
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string.")
    if not isinstance(creator_account_id, str) or not creator_account_id.strip():
        return _err("VALIDATION_ERROR", "creator_account_id must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    if not isinstance(decimals, int) or decimals < 0 or decimals > 18:
        return _err("VALIDATION_ERROR", "decimals must be an integer between 0 and 18.")
    if not isinstance(metadata_uri, str) or not metadata_uri.strip():
        return _err("VALIDATION_ERROR", "metadata_uri must be a non-empty string.")

    accounts = _load("accounts.json")
    tokens = _load("tokens.json")
    rpc_requests = _load("rpc_requests.json")

    acct = next((a for a in accounts if a.get("id") == creator_account_id), None)
    if acct is None:
        return _err("NOT_FOUND", "creator_account_id does not reference an existing account.")
    if acct.get("status") != "active":
        return _err("INVALID_TRANSITION", "Creator account is not active; cannot create token.", account_status=acct.get("status"))

    # Idempotency: find existing by request_id
    existing = next((t for t in tokens if t.get("create_request_id") == request_id), None)
    if existing is not None:
        # Reject if input fields differ
        mismatch = {}
        if existing.get("creator_account_id") != creator_account_id: mismatch["creator_account_id"] = True
        if (existing.get("name") or "") != name: mismatch["name"] = True
        if (existing.get("symbol") or "") != symbol: mismatch["symbol"] = True
        if existing.get("decimals") != decimals: mismatch["decimals"] = True
        if (existing.get("metadata_uri") or "") != metadata_uri: mismatch["metadata_uri"] = True
        if mismatch:
            return _err("CONFLICT", "request_id already used with different parameters.", mismatched_fields=sorted(mismatch.keys()))
        return {"token": existing, "idempotent": True, "latency_ms": int((time.time() - t0) * 1000)}

    def _new_id(prefix):
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        return f"{prefix}_{ts}_{random.randrange(10**8, 10**9)}"

    def _log_rpc(tool_name, account_id_val, token_id_val, rpc_method, rpc_params, http_status=None, rpc_error=None, duration_ms=None):
        rid = _new_id("rpcreq")
        row = {
            "id": rid,
            "tool_name": tool_name,
            "account_id": account_id_val,
            "token_id": token_id_val,
            "trade_id": None,
            "rpc_method": rpc_method,
            "rpc_params": rpc_params,
            "http_status": http_status,
            "rpc_error": rpc_error,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        rpc_requests.append(row)
        _save("rpc_requests.json", rpc_requests)
        return row

    # Create token in 'creating'
    token_id = _new_id("tok_pump")
    token = {
        "id": token_id,
        "mint_address": _new_id("mint")[:44].replace("_", ""),  # placeholder-ish; not real base58 but unique
        "pump_market_address": None,
        "creator_account_id": creator_account_id,
        "name": name,
        "symbol": symbol,
        "decimals": decimals,
        "metadata_uri": metadata_uri,
        "status": "creating",
        "create_request_id": request_id,
        "create_tx_signature": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(create_request_id) already ensured; unique(mint_address)
    if any(t.get("mint_address") == token["mint_address"] for t in tokens):
        # regenerate a couple times
        for _ in range(5):
            token["mint_address"] = _new_id("mint")[:44].replace("_", "")
            if not any(t.get("mint_address") == token["mint_address"] for t in tokens):
                break
        if any(t.get("mint_address") == token["mint_address"] for t in tokens):
            return _err("CONFLICT", "Unable to allocate unique mint_address.")
    tokens.append(token)
    _save("tokens.json", tokens)

    # Simulate RPC: build + send + confirm; always record rpc_requests and transition per rules.
    rpc_t0 = time.time()
    _log_rpc(
        "create-token",
        creator_account_id,
        token_id,
        "sendTransaction",
        {"action": "create_pump_token", "creator_public_key": acct.get("public_key"), "name": name, "symbol": symbol, "decimals": decimals, "metadata_uri": metadata_uri},
        http_status=200,
        rpc_error=None,
        duration_ms=int((time.time() - rpc_t0) * 1000),
    )

    # Mark submitted and confirmed immediately for offline behavior
    token["create_tx_signature"] = _new_id("txsig")
    token["updated_at"] = now

    # Transition creating -> live (legal)
    token["status"] = "live"
    token["updated_at"] = now
    _save("tokens.json", tokens)

    return {"token": token, "idempotent": False, "latency_ms": int((time.time() - t0) * 1000)}

def buy_token(request_id, account_id, token_id, amount_in_raw, slippage_bps, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _sanitize_params(d):
        if not isinstance(d, dict):
            return None
        banned = {"secret", "private", "seed", "mnemonic", "key", "bytes", "raw_key"}
        out = {}
        for k, v in d.items():
            if not isinstance(k, str):
                continue
            lk = k.lower()
            if any(b in lk for b in banned):
                continue
            if v is None or isinstance(v, (str, int, float, bool)):
                out[k] = v
            else:
                out[k] = "[redacted_complex]"
        return out

    def _log_rpc(http_status, rpc_method, rpc_params, account_id=None, token_id=None, trade_id=None, rpc_error=None):
        rpc_requests = _load("rpc_requests.json")
        rpc_requests.append({
            "id": "rpc_" + secrets.token_hex(12),
            "tool_name": "buy-token",
            "account_id": account_id,
            "token_id": token_id,
            "trade_id": trade_id,
            "rpc_method": rpc_method,
            "rpc_params": _sanitize_params(rpc_params),
            "http_status": int(http_status) if http_status is not None else None,
            "rpc_error": rpc_error,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("rpc_requests.json", rpc_requests)

    # Validate inputs
    if not isinstance(request_id, str) or not request_id.strip():
        _log_rpc(400, "createTrade", {"request_id": request_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "request_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string.")
    if not isinstance(account_id, str) or not account_id.strip():
        _log_rpc(400, "createTrade", {"account_id": account_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "account_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    if not isinstance(token_id, str) or not token_id.strip():
        _log_rpc(400, "createTrade", {"token_id": token_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "token_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string.")
    if not isinstance(amount_in_raw, str) or not re.fullmatch(r"^[0-9]+$", amount_in_raw or ""):
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "amount_in_raw must be a string integer."})
        return _err("VALIDATION_ERROR", "amount_in_raw must be a string integer.")
    try:
        amt = int(amount_in_raw)
    except ValueError:
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "amount_in_raw must be a string integer."})
        return _err("VALIDATION_ERROR", "amount_in_raw must be a string integer.")
    if amt <= 0:
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "Trade amount must be > 0."})
        return _err("VALIDATION_ERROR", "Trade amount must be > 0.")
    if not isinstance(slippage_bps, int) or slippage_bps < 0 or slippage_bps > 10000:
        _log_rpc(400, "createTrade", {"slippage_bps": slippage_bps}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "slippage_bps must be an integer between 0 and 10000."})
        return _err("VALIDATION_ERROR", "slippage_bps must be an integer between 0 and 10000.")

    accounts = _load("accounts.json")
    tokens = _load("tokens.json")
    trades = _load("trades.json")

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        _log_rpc(404, "createTrade", {"account_id": account_id, "token_id": token_id}, account_id=account_id, token_id=token_id, rpc_error={"code": "NOT_FOUND", "message": "account_id not found."})
        return _err("NOT_FOUND", "account_id not found.", account_id=account_id)

    tok = next((t for t in tokens if isinstance(t, dict) and t.get("id") == token_id), None)
    if tok is None:
        _log_rpc(404, "createTrade", {"account_id": account_id, "token_id": token_id}, account_id=account_id, token_id=token_id, rpc_error={"code": "NOT_FOUND", "message": "token_id not found."})
        return _err("NOT_FOUND", "token_id not found.", token_id=token_id)

    # Idempotency: return existing trade for request_id (do not enforce parameter-equality conflict; vendor audit expects data return)
    existing = next((tr for tr in trades if isinstance(tr, dict) and tr.get("request_id") == request_id), None)
    if existing is not None:
        _log_rpc(200, "getTradeByRequestId", {"request_id": request_id}, account_id=existing.get("account_id"), token_id=existing.get("token_id"), trade_id=existing.get("id"))
        return {"trade": existing}

    # Business rule: cannot submit if acct not active or token not live; we still create queued trade, but record failed immediately.
    trade_status = "queued"
    failure_reason = None
    if acct.get("status") != "active":
        trade_status = "failed"
        failure_reason = f"Account not active: signing account is {acct.get('status')}"
    elif tok.get("status") not in ("live",):
        trade_status = "failed"
        failure_reason = f"Token not live: token status is {tok.get('status')}"

    trade_id = "trd_pump_" + secrets.token_hex(12)
    row = {
        "id": trade_id,
        "side": "buy",
        "account_id": account_id,
        "token_id": token_id,
        "request_id": request_id,
        "requested_input_mint": None,
        "requested_output_mint": None,
        "amount_in_raw": amount_in_raw,
        "amount_out_raw": None,
        "slippage_bps": slippage_bps,
        "status": trade_status,
        "failure_reason": failure_reason,
        "tx_signature": None,
        "confirmed_slot": None,
        "created_at": now,
        "updated_at": now,
    }
    trades.append(row)
    _save("trades.json", trades)

    _log_rpc(200, "createTrade", {"request_id": request_id, "side": "buy"}, account_id=account_id, token_id=token_id, trade_id=trade_id, rpc_error=None if trade_status != "failed" else {"code": "FAILED_PRECONDITION", "message": failure_reason})

    return {"trade": row}

def sell_token(request_id, account_id, token_id, amount_in_raw, slippage_bps, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _sanitize_params(d):
        if not isinstance(d, dict):
            return None
        banned = {"secret", "private", "seed", "mnemonic", "key", "bytes", "raw_key"}
        out = {}
        for k, v in d.items():
            if not isinstance(k, str):
                continue
            lk = k.lower()
            if any(b in lk for b in banned):
                continue
            if v is None or isinstance(v, (str, int, float, bool)):
                out[k] = v
            else:
                out[k] = "[redacted_complex]"
        return out

    def _log_rpc(http_status, rpc_method, rpc_params, account_id=None, token_id=None, trade_id=None, rpc_error=None):
        rpc_requests = _load("rpc_requests.json")
        rpc_requests.append({
            "id": "rpc_" + secrets.token_hex(12),
            "tool_name": "sell-token",
            "account_id": account_id,
            "token_id": token_id,
            "trade_id": trade_id,
            "rpc_method": rpc_method,
            "rpc_params": _sanitize_params(rpc_params),
            "http_status": int(http_status) if http_status is not None else None,
            "rpc_error": rpc_error,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("rpc_requests.json", rpc_requests)

    # Validate inputs
    if not isinstance(request_id, str) or not request_id.strip():
        _log_rpc(400, "createTrade", {"request_id": request_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "request_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string.")
    if not isinstance(account_id, str) or not account_id.strip():
        _log_rpc(400, "createTrade", {"account_id": account_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "account_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    if not isinstance(token_id, str) or not token_id.strip():
        _log_rpc(400, "createTrade", {"token_id": token_id}, rpc_error={"code": "VALIDATION_ERROR", "message": "token_id must be a non-empty string."})
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string.")
    if not isinstance(amount_in_raw, str) or not re.fullmatch(r"^[0-9]+$", amount_in_raw or ""):
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "amount_in_raw must be a string integer."})
        return _err("VALIDATION_ERROR", "amount_in_raw must be a string integer.")
    try:
        amt = int(amount_in_raw)
    except ValueError:
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "amount_in_raw must be a string integer."})
        return _err("VALIDATION_ERROR", "amount_in_raw must be a string integer.")
    if amt <= 0:
        _log_rpc(400, "createTrade", {"amount_in_raw": amount_in_raw}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "Trade amount must be > 0."})
        return _err("VALIDATION_ERROR", "Trade amount must be > 0.")
    if not isinstance(slippage_bps, int) or slippage_bps < 0 or slippage_bps > 10000:
        _log_rpc(400, "createTrade", {"slippage_bps": slippage_bps}, account_id=account_id, token_id=token_id, rpc_error={"code": "VALIDATION_ERROR", "message": "slippage_bps must be an integer between 0 and 10000."})
        return _err("VALIDATION_ERROR", "slippage_bps must be an integer between 0 and 10000.")

    accounts = _load("accounts.json")
    tokens = _load("tokens.json")
    trades = _load("trades.json")

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        _log_rpc(404, "createTrade", {"account_id": account_id, "token_id": token_id}, account_id=account_id, token_id=token_id, rpc_error={"code": "NOT_FOUND", "message": "account_id not found."})
        return _err("NOT_FOUND", "account_id not found.", account_id=account_id)

    tok = next((t for t in tokens if isinstance(t, dict) and t.get("id") == token_id), None)
    if tok is None:
        _log_rpc(404, "createTrade", {"account_id": account_id, "token_id": token_id}, account_id=account_id, token_id=token_id, rpc_error={"code": "NOT_FOUND", "message": "token_id not found."})
        return _err("NOT_FOUND", "token_id not found.", token_id=token_id)

    # Idempotency: return existing trade for request_id
    existing = next((tr for tr in trades if isinstance(tr, dict) and tr.get("request_id") == request_id), None)
    if existing is not None:
        _log_rpc(200, "getTradeByRequestId", {"request_id": request_id}, account_id=existing.get("account_id"), token_id=existing.get("token_id"), trade_id=existing.get("id"))
        return {"trade": existing}

    trade_status = "queued"
    failure_reason = None
    if acct.get("status") != "active":
        trade_status = "failed"
        failure_reason = f"Account not active: signing account is {acct.get('status')}"
    elif tok.get("status") not in ("live",):
        trade_status = "failed"
        failure_reason = f"Token not live: token status is {tok.get('status')}"

    trade_id = "trd_pump_" + secrets.token_hex(12)
    # Tool param is amount_in_raw, but schema expects amount_out_raw for sells.
    row = {
        "id": trade_id,
        "side": "sell",
        "account_id": account_id,
        "token_id": token_id,
        "request_id": request_id,
        "requested_input_mint": None,
        "requested_output_mint": None,
        "amount_in_raw": None,
        "amount_out_raw": amount_in_raw,
        "slippage_bps": slippage_bps,
        "status": trade_status,
        "failure_reason": failure_reason,
        "tx_signature": None,
        "confirmed_slot": None,
        "created_at": now,
        "updated_at": now,
    }
    trades.append(row)
    _save("trades.json", trades)

    _log_rpc(200, "createTrade", {"request_id": request_id, "side": "sell"}, account_id=account_id, token_id=token_id, trade_id=trade_id, rpc_error=None if trade_status != "failed" else {"code": "FAILED_PRECONDITION", "message": failure_reason})

    return {"trade": row}

def list_accounts(status=None, key_source=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    allowed_status = {"active", "disabled", "missing_key", "compromised"}
    allowed_key_source = {"keys_folder", "imported"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))
    if key_source is not None and (not isinstance(key_source, str) or key_source not in allowed_key_source):
        return _err("VALIDATION_ERROR", "Invalid key_source.", allowed=sorted(list(allowed_key_source)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0:
        return _err("VALIDATION_ERROR", "limit must be a positive integer.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Load
    accounts = _load("accounts.json")
    rpc_requests = _load("rpc_requests.json")

    # Cursor is simple numeric offset as string
    if cursor is None or cursor == "":
        offset = 0
    else:
        if not re.fullmatch(r"[0-9]+", cursor):
            # audit before returning
            rpc_requests.append({
                "id": f"rpc_{secrets.token_hex(12)}",
                "tool_name": "list-accounts",
                "account_id": None,
                "token_id": None,
                "trade_id": None,
                "rpc_method": "local.listAccounts",
                "rpc_params": {"status": status, "key_source": key_source, "limit": limit, "cursor": cursor},
                "http_status": 400,
                "rpc_error": {"code": "VALIDATION_ERROR", "message": "Invalid cursor."},
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "created_at": now,
                "updated_at": now
            })
            _save("rpc_requests.json", rpc_requests)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        offset = int(cursor)

    # Business rule: list-accounts returns accounts where key_source='keys_folder' and status != 'compromised'
    # Also: if key file missing, set status='missing_key' and last_seen_at=now.
    keys_dir = os.path.join(_DB, "keys")
    changed = False
    eligible = []
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if a.get("key_source") != "keys_folder":
            continue
        if a.get("status") == "compromised":
            continue

        # Missing key file check for keys_folder
        key_ref = a.get("key_ref")
        # key_ref required and non-empty per constraints; if empty, treat as missing
        missing = True
        if isinstance(key_ref, str) and key_ref.strip():
            path = os.path.join(keys_dir, key_ref)
            missing = not os.path.exists(path)
        if missing:
            if a.get("status") != "missing_key" or a.get("last_seen_at") != now:
                # allowed transitions: active->missing_key, missing_key->missing_key(no-op), disabled->? not allowed directly
                # But business rule requires setting missing_key when file missing.
                # If currently disabled, set to missing_key only if allowed? transitions: disabled -> active only.
                # We'll keep disabled as-is but still set last_seen_at.
                if a.get("status") in ("active", "missing_key"):
                    a["status"] = "missing_key"
                a["last_seen_at"] = now
                a["updated_at"] = now
                changed = True
        else:
            # key exists: update last_seen_at
            a["last_seen_at"] = now
            a["updated_at"] = now
            changed = True

        # Apply optional filters after baseline rule
        if status is not None and a.get("status") != status:
            continue
        if key_source is not None and a.get("key_source") != key_source:
            continue
        eligible.append(a)

    # Deterministic sort for pagination
    eligible.sort(key=lambda r: (str(r.get("created_at") or ""), str(r.get("id") or "")))

    total = len(eligible)
    if offset < 0 or offset > total:
        rpc_requests.append({
            "id": f"rpc_{secrets.token_hex(12)}",
            "tool_name": "list-accounts",
            "account_id": None,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.listAccounts",
            "rpc_params": {"status": status, "key_source": key_source, "limit": limit, "cursor": cursor},
            "http_status": 400,
            "rpc_error": {"code": "VALIDATION_ERROR", "message": "Invalid cursor offset."},
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = eligible[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    if changed:
        _save("accounts.json", accounts)

    # Audit: every call records an rpc_requests row (sanitized params)
    rpc_requests.append({
        "id": f"rpc_{secrets.token_hex(12)}",
        "tool_name": "list-accounts",
        "account_id": None,
        "token_id": None,
        "trade_id": None,
        "rpc_method": "local.listAccounts",
        "rpc_params": {"status": status, "key_source": key_source, "limit": limit, "cursor": cursor},
        "http_status": 200,
        "rpc_error": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now,
        "updated_at": now
    })
    _save("rpc_requests.json", rpc_requests)

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}
    }

def get_account_balance(account_id, asset_type=None, mint_address=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, secrets, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(account_id, str) or not account_id.strip():
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    # described format: acct_sol_... ULID
    if not account_id.startswith("acct_sol_"):
        return _err("VALIDATION_ERROR", "account_id is malformed.")
    allowed_asset = {"SOL", "SPL"}
    if asset_type is not None and (not isinstance(asset_type, str) or asset_type not in allowed_asset):
        return _err("VALIDATION_ERROR", "Invalid asset_type.", allowed=sorted(list(allowed_asset)))
    if mint_address is not None:
        if not isinstance(mint_address, str) or not mint_address.strip():
            return _err("VALIDATION_ERROR", "mint_address must be a non-empty string when provided.")
        if asset_type != "SPL":
            return _err("VALIDATION_ERROR", "mint_address filter requires asset_type='SPL'.")
        # base58-ish and length constraint
        if not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", mint_address):
            return _err("VALIDATION_ERROR", "mint_address is not a valid base58 address length 32-44.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0:
        return _err("VALIDATION_ERROR", "limit must be a positive integer.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    accounts = _load("accounts.json")
    balances = _load("account_balances.json")
    rpc_requests = _load("rpc_requests.json")

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        rpc_requests.append({
            "id": f"rpc_{secrets.token_hex(12)}",
            "tool_name": "get-account-balance",
            "account_id": account_id,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "getBalance+getTokenAccountsByOwner",
            "rpc_params": {"account_id": account_id, "asset_type": asset_type, "mint_address": mint_address},
            "http_status": 404,
            "rpc_error": {"code": "NOT_FOUND", "message": "Account not found."},
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return _err("NOT_FOUND", "No account exists for the given account_id.")

    # Cursor numeric offset
    if cursor is None or cursor == "":
        offset = 0
    else:
        if not re.fullmatch(r"[0-9]+", cursor):
            rpc_requests.append({
                "id": f"rpc_{secrets.token_hex(12)}",
                "tool_name": "get-account-balance",
                "account_id": account_id,
                "token_id": None,
                "trade_id": None,
                "rpc_method": "local.getAccountBalance",
                "rpc_params": {"account_id": account_id, "asset_type": asset_type, "mint_address": mint_address, "limit": limit, "cursor": cursor},
                "http_status": 400,
                "rpc_error": {"code": "VALIDATION_ERROR", "message": "Invalid cursor."},
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "created_at": now,
                "updated_at": now
            })
            _save("rpc_requests.json", rpc_requests)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        offset = int(cursor)

    # Business rule: must upsert account_balances for SOL and any discovered SPL token accounts;
    # refreshed_at must be updated on every successful fetch.
    # Offline behavior: treat "discovered SPL token accounts" as existing SPL rows for this account,
    # plus (optionally) any mints that exist in tokens.json that this account has a balance row for.
    # Always upsert SOL row.
    changed = False

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _find_balance_row(acct_id, atype, mint):
        for r in balances:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") == acct_id and r.get("asset_type") == atype and r.get("mint_address") == mint:
                return r
        return None

    # SOL upsert
    sol_row = _find_balance_row(account_id, "SOL", None)
    if sol_row is None:
        sol_row = {
            "id": _gen_id("bal"),
            "account_id": account_id,
            "asset_type": "SOL",
            "mint_address": None,
            "amount_raw": "0",
            "decimals": None,
            "slot": None,
            "refreshed_at": now,
            "created_at": now,
            "updated_at": now
        }
        balances.append(sol_row)
        changed = True
    else:
        sol_row["refreshed_at"] = now
        sol_row["updated_at"] = now
        changed = True

    # "Fetch" simulated updated amounts deterministically based on public key + date bucket (no secrets).
    # Keep as string ints; ensure non-negative.
    def _pseudo_amount(seed_text, modulus):
        h = 0
        for ch in seed_text:
            h = (h * 131 + ord(ch)) % 2_147_483_647
        return str(h % modulus)

    pub = str(acct.get("public_key") or "")
    day_bucket = now[:10]
    sol_row["amount_raw"] = _pseudo_amount(pub + "|SOL|" + day_bucket, 10_000_000_000)  # lamports-ish

    # SPL refresh: update any existing SPL rows for this account (and respect constraints)
    for r in balances:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id or r.get("asset_type") != "SPL":
            continue
        mint = r.get("mint_address")
        if not isinstance(mint, str) or not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,44}", mint):
            # keep row but don't attempt to "fetch"; still mark refreshed to show attempted discovery
            r["refreshed_at"] = now
            r["updated_at"] = now
            changed = True
            continue
        r["refreshed_at"] = now
        r["updated_at"] = now
        # if decimals unknown, keep null; else validate range
        dec = r.get("decimals")
        if dec is not None and (not isinstance(dec, int) or dec < 0 or dec > 18):
            r["decimals"] = None
        r["amount_raw"] = _pseudo_amount(pub + "|SPL|" + mint + "|" + day_bucket, 1_000_000_000_000)
        # slot: simulate
        r["slot"] = int(_pseudo_amount(pub + "|slot|" + day_bucket, 1_000_000_000))
        changed = True

    if changed:
        _save("account_balances.json", balances)

    # Filter/paginate response
    rows = [r for r in balances if isinstance(r, dict) and r.get("account_id") == account_id]
    if asset_type is not None:
        rows = [r for r in rows if r.get("asset_type") == asset_type]
    if asset_type == "SPL" and mint_address is not None:
        rows = [r for r in rows if r.get("mint_address") == mint_address]

    rows.sort(key=lambda r: (str(r.get("asset_type") or ""), str(r.get("mint_address") or ""), str(r.get("id") or "")))

    total = len(rows)
    if offset < 0 or offset > total:
        rpc_requests.append({
            "id": f"rpc_{secrets.token_hex(12)}",
            "tool_name": "get-account-balance",
            "account_id": account_id,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.getAccountBalance",
            "rpc_params": {"account_id": account_id, "asset_type": asset_type, "mint_address": mint_address, "limit": limit, "cursor": cursor},
            "http_status": 400,
            "rpc_error": {"code": "VALIDATION_ERROR", "message": "Invalid cursor offset."},
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    # Audit RPC row (sanitized)
    rpc_requests.append({
        "id": f"rpc_{secrets.token_hex(12)}",
        "tool_name": "get-account-balance",
        "account_id": account_id,
        "token_id": None,
        "trade_id": None,
        "rpc_method": "getBalance+getTokenAccountsByOwner",
        "rpc_params": {"public_key": pub, "filters": {"asset_type": asset_type, "mint_address": mint_address}},
        "http_status": 200,
        "rpc_error": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now,
        "updated_at": now
    })
    _save("rpc_requests.json", rpc_requests)

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}
    }

def get_account(account_id, **_extra):
