            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return _err("NOT_FOUND", "No account exists for the given account_id.")

    a = accounts[idx]

    # If key file missing on disk, update to missing_key + last_seen_at now before returning.
    changed = False
    if a.get("key_source") == "keys_folder":
        keys_dir = os.path.join(_DB, "keys")
        key_ref = a.get("key_ref")
        missing = True
        if isinstance(key_ref, str) and key_ref.strip():
            missing = not os.path.exists(os.path.join(keys_dir, key_ref))
        if missing:
            if a.get("status") in ("active", "missing_key"):
                if a.get("status") != "missing_key":
                    a["status"] = "missing_key"
                    changed = True
            # even if disabled, still update last_seen_at to reflect check
            a["last_seen_at"] = now
            a["updated_at"] = now
            changed = True
        else:
            a["last_seen_at"] = now
            a["updated_at"] = now
            changed = True

    if changed:
        accounts[idx] = a
        _save("accounts.json", accounts)

    # Audit
    rpc_requests.append({
        "id": f"rpc_{secrets.token_hex(12)}",
        "tool_name": "get-account",
        "account_id": account_id,
        "token_id": None,
        "trade_id": None,
        "rpc_method": "local.getAccount",
        "rpc_params": {"account_id": account_id},
        "http_status": 200,
        "rpc_error": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now,
        "updated_at": now
    })
    _save("rpc_requests.json", rpc_requests)

    return {"data": a}

def update_account(account_id, label=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(account_id, str) or not account_id.strip() or not account_id.startswith("acct_sol_"):
        return _err("VALIDATION_ERROR", "account_id is malformed.")

    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string.")
    if label is not None and label.strip() == "":
        return _err("VALIDATION_ERROR", "label cannot be empty when provided.")

    allowed_status = {"active", "disabled", "missing_key", "compromised"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))

    accounts = _load("accounts.json")
    rpc_requests = _load("rpc_requests.json")

    idx = None
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == account_id:
            idx = i
            break
    if idx is None:
        rpc_requests.append({
            "id": f"rpc_{secrets.token_hex(12)}",
            "tool_name": "update-account",
            "account_id": account_id,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.updateAccount",
            "rpc_params": {"account_id": account_id, "label": label, "status": status},
            "http_status": 404,
            "rpc_error": {"code": "NOT_FOUND", "message": "Account not found."},
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return _err("NOT_FOUND", "No account exists for the given account_id.")

    a = accounts[idx]
    original = dict(a)

    # Enforce unique(label) where label not null
    if label is not None:
        for other in accounts:
            if not isinstance(other, dict):
                continue
            if other.get("id") != account_id and other.get("label") is not None and other.get("label") == label:
                rpc_requests.append({
                    "id": f"rpc_{secrets.token_hex(12)}",
                    "tool_name": "update-account",
                    "account_id": account_id,
                    "token_id": None,
                    "trade_id": None,
                    "rpc_method": "local.updateAccount",
                    "rpc_params": {"account_id": account_id, "label": label, "status": status},
                    "http_status": 409,
                    "rpc_error": {"code": "CONFLICT", "message": "label must be unique."},
                    "duration_ms": max(0, int((time.time() - t0) * 1000)),
                    "created_at": now,
                    "updated_at": now
                })
                _save("rpc_requests.json", rpc_requests)
                return _err("CONFLICT", "label must be unique.")
        a["label"] = label

    # Lifecycle transitions for accounts.status
    transitions = {
        "active": {"disabled", "missing_key", "compromised"},
        "disabled": {"active"},
        "missing_key": {"active", "disabled"},
        "compromised": {"disabled"},
    }
    if status is not None:
        cur = a.get("status")
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Current account status is invalid.")
        if status != cur and status not in transitions.get(cur, set()):
            rpc_requests.append({
                "id": f"rpc_{secrets.token_hex(12)}",
                "tool_name": "update-account",
                "account_id": account_id,
                "token_id": None,
                "trade_id": None,
                "rpc_method": "local.updateAccount",
                "rpc_params": {"account_id": account_id, "label": label, "status": status},
                "http_status": 409,
                "rpc_error": {"code": "INVALID_TRANSITION", "message": f"Disallowed status transition {cur}->{status}."},
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "created_at": now,
                "updated_at": now
            })
            _save("rpc_requests.json", rpc_requests)
            return _err("INVALID_TRANSITION", f"Disallowed status transition {cur}->{status}.")
        a["status"] = status

    # If nothing changed, return current record (idempotent update)
    if a == original:
        rpc_requests.append({
            "id": f"rpc_{secrets.token_hex(12)}",
            "tool_name": "update-account",
            "account_id": account_id,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.updateAccount",
            "rpc_params": {"account_id": account_id, "label": label, "status": status},
            "http_status": 200,
            "rpc_error": None,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now
        })
        _save("rpc_requests.json", rpc_requests)
        return {"data": a}

    a["updated_at"] = now
    accounts[idx] = a
    _save("accounts.json", accounts)

    rpc_requests.append({
        "id": f"rpc_{secrets.token_hex(12)}",
        "tool_name": "update-account",
        "account_id": account_id,
        "token_id": None,
        "trade_id": None,
        "rpc_method": "local.updateAccount",
        "rpc_params": {"account_id": account_id, "label": label, "status": status},
        "http_status": 200,
        "rpc_error": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now,
        "updated_at": now
    })
    _save("rpc_requests.json", rpc_requests)

    return {"data": a}

def list_tokens(creator_account_id=None, status=None, mint_address=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- rate-limit/quota + request logging helpers ---
    def _load_rl():
        return _load("rate_limits.json")
    def _save_rl(d):
        _save("rate_limits.json", d)

    def _log_request(tool_name, credential_id, status_code, latency_ms, extra=None):
        logs = _load("rpc_requests.json")
        # tool_name enum includes list-accounts/get-account-balance etc; list-tokens isn't in enum.
        # Still log for observable dynamics; keep within enum by using closest tool identifier.
        logged_tool = tool_name if tool_name in {
            "get-token-info", "create-token", "buy-token", "sell-token", "list-accounts", "get-account-balance"
        } else "get-token-info"
        rid = "rpc_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "tool_name": logged_tool,
            "account_id": None,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.list",
            "rpc_params": extra if isinstance(extra, dict) else None,
            "http_status": int(status_code),
            "rpc_error": None if 200 <= int(status_code) < 400 else {"code": int(status_code), "message": "request_failed"},
            "duration_ms": int(latency_ms),
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("rpc_requests.json", logs)

    def _enforce_limits(credential_id):
        # default limits if store missing: generous but finite
        rl = _load_rl()
        rec = None
        for r in rl:
            if r.get("credential_id") == credential_id:
                rec = r
                break
        if rec is None:
            rec = {
                "credential_id": credential_id,
                "window_seconds": 60,
                "max_requests_per_window": 120,
                "day": now[:10],
                "max_requests_per_day": 5000,
                "request_timestamps": [],
                "requests_today": 0,
                "updated_at": now,
            }
            rl.append(rec)

        window = rec.get("window_seconds", 60)
        maxw = rec.get("max_requests_per_window", 120)
        maxd = rec.get("max_requests_per_day", 5000)

        # reset day if needed
        if rec.get("day") != now[:10]:
            rec["day"] = now[:10]
            rec["requests_today"] = 0
            rec["request_timestamps"] = []

        # prune window
        ts = rec.get("request_timestamps") or []
        cutoff = time.time() - float(window)
        ts = [x for x in ts if isinstance(x, (int, float)) and x >= cutoff]

        if len(ts) >= int(maxw):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window, max_requests_per_window=maxw)

        if int(rec.get("requests_today", 0)) >= int(maxd):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", max_requests_per_day=maxd)

        # consume
        ts.append(time.time())
        rec["request_timestamps"] = ts
        rec["requests_today"] = int(rec.get("requests_today", 0)) + 1
        rec["updated_at"] = now
        _save_rl(rl)
        return None

    # --- ambient auth resolution (best available) ---
    def _resolve_ambient_credential():
        # prefer an "active" api_keys row if present; else fall back to first account as identity
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list) and api_keys:
            for k in api_keys:
                if k.get("status") in (None, "active"):
                    return ("api_key", k.get("id") or k.get("api_key") or "key_unknown", k)
            k = api_keys[0]
            return ("api_key", k.get("id") or k.get("api_key") or "key_unknown", k)
        accounts = _load("accounts.json")
        if accounts:
            return ("account", accounts[0].get("id") or "acct_unknown", accounts[0])
        return (None, None, None)

    auth_kind, cred_id, cred_row = _resolve_ambient_credential()
    if cred_id is None:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", None, 401, latency_ms, extra={"reason": "no_identity"})
        return _err("UNAUTHORIZED", "No authenticated identity is available.")

    limit_err = _enforce_limits(cred_id)
    if limit_err:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 429 if limit_err["error"]["code"] == "RATE_LIMIT" else 403, latency_ms)
        return limit_err

    # --- validate inputs ---
    if creator_account_id is not None and not isinstance(creator_account_id, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "creator_account_id must be a string.")
    if status is not None:
        if not isinstance(status, str):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-tokens", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ["draft", "creating", "live", "failed", "archived"]:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-tokens", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["draft", "creating", "live", "failed", "archived"])
    if mint_address is not None and not isinstance(mint_address, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "mint_address must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit <= 0:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "limit must be positive.")
    if cursor is not None and not isinstance(cursor, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-tokens", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # validate cursor format and decode
    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start_after = raw.decode("utf-8")
        except Exception:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-tokens", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # if creator filter supplied, ensure referenced account exists (FK validation for filter)
    if creator_account_id:
        accounts = _load("accounts.json")
        if not any(a.get("id") == creator_account_id for a in accounts):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-tokens", cred_id, 404, latency_ms)
            return _err("NOT_FOUND", "creator_account_id does not reference an existing account.")

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []

    # filter
    def _match(t):
        if creator_account_id is not None and t.get("creator_account_id") != creator_account_id:
            return False
        if status is not None and t.get("status") != status:
            return False
        if mint_address is not None and t.get("mint_address") != mint_address:
            return False
        return True

    filtered = [t for t in tokens if isinstance(t, dict) and _match(t)]

    # sort deterministic: created_at desc, then id desc
    def _k(t):
        return (t.get("created_at") or "", t.get("id") or "")
    filtered.sort(key=_k, reverse=True)

    # pagination using start_after id
    if start_after is not None:
        idx = None
        for i, t in enumerate(filtered):
            if t.get("id") == start_after:
                idx = i
                break
        if idx is None:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-tokens", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        filtered = filtered[idx + 1 :]

    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        nid = page[-1].get("id")
        if isinstance(nid, str) and nid:
            next_cursor = base64.urlsafe_b64encode(nid.encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = (time.time() - t0) * 1000
    _log_request("list-tokens", cred_id, 200, latency_ms, extra={"filters": {"creator_account_id": creator_account_id, "status": status, "mint_address": mint_address}, "limit": limit})

    return {
        "data": page,
        "meta": {
            "total": len([t for t in tokens if isinstance(t, dict) and _match(t)]),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }

def update_token(token_id, name=None, symbol=None, metadata_uri=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_rl():
        return _load("rate_limits.json")
    def _save_rl(d):
        _save("rate_limits.json", d)

    def _log_request(tool_name, credential_id, status_code, latency_ms, extra=None, token=None):
        logs = _load("rpc_requests.json")
        logged_tool = tool_name if tool_name in {
            "get-token-info", "create-token", "buy-token", "sell-token", "list-accounts", "get-account-balance"
        } else "get-token-info"
        rid = "rpc_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "tool_name": logged_tool,
            "account_id": None,
            "token_id": token.get("id") if isinstance(token, dict) else None,
            "trade_id": None,
            "rpc_method": "local.update",
            "rpc_params": extra if isinstance(extra, dict) else None,
            "http_status": int(status_code),
            "rpc_error": None if 200 <= int(status_code) < 400 else {"code": int(status_code), "message": "request_failed"},
            "duration_ms": int(latency_ms),
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("rpc_requests.json", logs)

    def _enforce_limits(credential_id):
        rl = _load_rl()
        rec = None
        for r in rl:
            if r.get("credential_id") == credential_id:
                rec = r
                break
        if rec is None:
            rec = {
                "credential_id": credential_id,
                "window_seconds": 60,
                "max_requests_per_window": 120,
                "day": now[:10],
                "max_requests_per_day": 5000,
                "request_timestamps": [],
                "requests_today": 0,
                "updated_at": now,
            }
            rl.append(rec)

        window = rec.get("window_seconds", 60)
        maxw = rec.get("max_requests_per_window", 120)
        maxd = rec.get("max_requests_per_day", 5000)

        if rec.get("day") != now[:10]:
            rec["day"] = now[:10]
            rec["requests_today"] = 0
            rec["request_timestamps"] = []

        ts = rec.get("request_timestamps") or []
        cutoff = time.time() - float(window)
        ts = [x for x in ts if isinstance(x, (int, float)) and x >= cutoff]

        if len(ts) >= int(maxw):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window, max_requests_per_window=maxw)

        if int(rec.get("requests_today", 0)) >= int(maxd):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", max_requests_per_day=maxd)

        ts.append(time.time())
        rec["request_timestamps"] = ts
        rec["requests_today"] = int(rec.get("requests_today", 0)) + 1
        rec["updated_at"] = now
        _save_rl(rl)
        return None

    def _resolve_ambient_credential():
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list) and api_keys:
            for k in api_keys:
                if k.get("status") in (None, "active"):
                    return (k.get("id") or k.get("api_key") or "key_unknown", k)
            k = api_keys[0]
            return (k.get("id") or k.get("api_key") or "key_unknown", k)
        accounts = _load("accounts.json")
        if accounts:
            return (accounts[0].get("id") or "acct_unknown", accounts[0])
        return (None, None)

    cred_id, _ = _resolve_ambient_credential()
    if cred_id is None:
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", None, 401, latency_ms, extra={"reason": "no_identity"})
        return _err("UNAUTHORIZED", "No authenticated identity is available.")

    limit_err = _enforce_limits(cred_id)
    if limit_err:
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", cred_id, 429 if limit_err["error"]["code"] == "RATE_LIMIT" else 403, latency_ms)
        return limit_err

    # validate inputs
    if not isinstance(token_id, str) or not token_id:
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "token_id must be a non-empty string.")
    for field_name, val in [("name", name), ("symbol", symbol), ("metadata_uri", metadata_uri)]:
        if val is not None and not isinstance(val, str):
            latency_ms = (time.time() - t0) * 1000
            _log_request("update-token", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", f"{field_name} must be a string.")
    if status is not None:
        if not isinstance(status, str):
            latency_ms = (time.time() - t0) * 1000
            _log_request("update-token", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ["draft", "creating", "live", "failed", "archived"]:
            latency_ms = (time.time() - t0) * 1000
            _log_request("update-token", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["draft", "creating", "live", "failed", "archived"])

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []

    idx = None
    tok = None
    for i, t in enumerate(tokens):
        if isinstance(t, dict) and t.get("id") == token_id:
            idx = i
            tok = t
            break
    if tok is None:
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", cred_id, 404, latency_ms, extra={"token_id": token_id})
        return _err("NOT_FOUND", "Token not found.", token_id=token_id)

    # lifecycle transitions
    transitions = {
        "draft": ["creating", "archived"],
        "creating": ["live", "failed"],
        "live": ["archived"],
        "failed": ["creating", "archived"],
        "archived": [],
    }

    updated = dict(tok)

    # immutable identifiers: mint_address and pump_market_address once set must not change.
    # (Tool doesn't accept them, but still enforce no implicit clearing.)
    # Apply mutable field updates
    if name is not None:
        updated["name"] = name
    if symbol is not None:
        updated["symbol"] = symbol
    if metadata_uri is not None:
        updated["metadata_uri"] = metadata_uri

    if status is not None and status != tok.get("status"):
        cur = tok.get("status")
        if cur not in transitions:
            latency_ms = (time.time() - t0) * 1000
            _log_request("update-token", cred_id, 409, latency_ms, token=tok)
            return _err("INVALID_TRANSITION", "Current token status is invalid.", current_status=cur)
        if status not in transitions.get(cur, []):
            latency_ms = (time.time() - t0) * 1000
            _log_request("update-token", cred_id, 409, latency_ms, token=tok)
            return _err("INVALID_TRANSITION", "Disallowed token status transition.", from_status=cur, to_status=status, allowed=transitions.get(cur, []))
        updated["status"] = status

    # ensure mint_address exists and doesn't violate uniqueness if changed (shouldn't change)
    if tok.get("mint_address") != updated.get("mint_address"):
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", cred_id, 409, latency_ms, token=tok)
        return _err("CONFLICT", "mint_address is immutable once set.")
    if tok.get("pump_market_address") and updated.get("pump_market_address") != tok.get("pump_market_address"):
        latency_ms = (time.time() - t0) * 1000
        _log_request("update-token", cred_id, 409, latency_ms, token=tok)
        return _err("CONFLICT", "pump_market_address is immutable once set.")

    updated["updated_at"] = now
    tokens[idx] = updated
    _save("tokens.json", tokens)

    latency_ms = (time.time() - t0) * 1000
    _log_request("update-token", cred_id, 200, latency_ms, extra={"token_id": token_id, "updated_fields": {"name": name is not None, "symbol": symbol is not None, "metadata_uri": metadata_uri is not None, "status": status is not None}}, token=updated)

    return {"data": updated}

def list_trades(account_id=None, token_id=None, side=None, status=None, request_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_rl():
        return _load("rate_limits.json")
    def _save_rl(d):
        _save("rate_limits.json", d)

    def _log_request(tool_name, credential_id, status_code, latency_ms, extra=None):
        logs = _load("rpc_requests.json")
        logged_tool = tool_name if tool_name in {
            "get-token-info", "create-token", "buy-token", "sell-token", "list-accounts", "get-account-balance"
        } else "get-token-info"
        rid = "rpc_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "tool_name": logged_tool,
            "account_id": None,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.list",
            "rpc_params": extra if isinstance(extra, dict) else None,
            "http_status": int(status_code),
            "rpc_error": None if 200 <= int(status_code) < 400 else {"code": int(status_code), "message": "request_failed"},
            "duration_ms": int(latency_ms),
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("rpc_requests.json", logs)

    def _enforce_limits(credential_id):
        rl = _load_rl()
        rec = None
        for r in rl:
            if r.get("credential_id") == credential_id:
                rec = r
                break
        if rec is None:
            rec = {
                "credential_id": credential_id,
                "window_seconds": 60,
                "max_requests_per_window": 120,
                "day": now[:10],
                "max_requests_per_day": 5000,
                "request_timestamps": [],
                "requests_today": 0,
                "updated_at": now,
            }
            rl.append(rec)

        window = rec.get("window_seconds", 60)
        maxw = rec.get("max_requests_per_window", 120)
        maxd = rec.get("max_requests_per_day", 5000)

        if rec.get("day") != now[:10]:
            rec["day"] = now[:10]
            rec["requests_today"] = 0
            rec["request_timestamps"] = []

        ts = rec.get("request_timestamps") or []
        cutoff = time.time() - float(window)
        ts = [x for x in ts if isinstance(x, (int, float)) and x >= cutoff]

        if len(ts) >= int(maxw):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window, max_requests_per_window=maxw)

        if int(rec.get("requests_today", 0)) >= int(maxd):
            rec["request_timestamps"] = ts
            rec["updated_at"] = now
            _save_rl(rl)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", max_requests_per_day=maxd)

        ts.append(time.time())
        rec["request_timestamps"] = ts
        rec["requests_today"] = int(rec.get("requests_today", 0)) + 1
        rec["updated_at"] = now
        _save_rl(rl)
        return None

    def _resolve_ambient_credential():
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list) and api_keys:
            for k in api_keys:
                if k.get("status") in (None, "active"):
                    return (k.get("id") or k.get("api_key") or "key_unknown", k)
            k = api_keys[0]
            return (k.get("id") or k.get("api_key") or "key_unknown", k)
        accounts = _load("accounts.json")
        if accounts:
            return (accounts[0].get("id") or "acct_unknown", accounts[0])
        return (None, None)

    cred_id, _ = _resolve_ambient_credential()
    if cred_id is None:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", None, 401, latency_ms, extra={"reason": "no_identity"})
        return _err("UNAUTHORIZED", "No authenticated identity is available.")

    limit_err = _enforce_limits(cred_id)
    if limit_err:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 429 if limit_err["error"]["code"] == "RATE_LIMIT" else 403, latency_ms)
        return limit_err

    # validate filters
    if account_id is not None and not isinstance(account_id, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "account_id must be a string.")
    if token_id is not None and not isinstance(token_id, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "token_id must be a string.")
    if side is not None:
        if not isinstance(side, str):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "side must be a string.")
        if side not in ["buy", "sell"]:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid side.", allowed=["buy", "sell"])
    if status is not None:
        if not isinstance(status, str):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ["queued", "building", "submitted", "confirmed", "failed", "cancelled"]:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["queued", "building", "submitted", "confirmed", "failed", "cancelled"])
    if request_id is not None and not isinstance(request_id, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "request_id must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit <= 0:
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "limit must be positive.")
    if cursor is not None and not isinstance(cursor, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request("list-trades", cred_id, 400, latency_ms)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start_after = raw.decode("utf-8")
        except Exception:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # FK validation for filter references when provided
    if account_id:
        accounts = _load("accounts.json")
        if not any(isinstance(a, dict) and a.get("id") == account_id for a in accounts):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 404, latency_ms)
            return _err("NOT_FOUND", "account_id does not reference an existing account.")
    if token_id:
        tokens = _load("tokens.json")
        if not any(isinstance(t, dict) and t.get("id") == token_id for t in tokens):
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 404, latency_ms)
            return _err("NOT_FOUND", "token_id does not reference an existing token.")

    trades = _load("trades.json")
    if not isinstance(trades, list):
        trades = []

    def _match(tr):
        if account_id is not None and tr.get("account_id") != account_id:
            return False
        if token_id is not None and tr.get("token_id") != token_id:
            return False
        if side is not None and tr.get("side") != side:
            return False
        if status is not None and tr.get("status") != status:
            return False
        if request_id is not None and tr.get("request_id") != request_id:
            return False
        return True

    filtered = [tr for tr in trades if isinstance(tr, dict) and _match(tr)]
    filtered.sort(key=lambda tr: (tr.get("created_at") or "", tr.get("id") or ""), reverse=True)

    if start_after is not None:
        idx = None
        for i, tr in enumerate(filtered):
            if tr.get("id") == start_after:
                idx = i
                break
        if idx is None:
            latency_ms = (time.time() - t0) * 1000
            _log_request("list-trades", cred_id, 400, latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        filtered = filtered[idx + 1 :]

    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str) and last_id:
            next_cursor = base64.urlsafe_b64encode(last_id.encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = (time.time() - t0) * 1000
    _log_request("list-trades", cred_id, 200, latency_ms, extra={"filters": {"account_id": account_id, "token_id": token_id, "side": side, "status": status, "request_id": request_id}, "limit": limit})

    return {
        "data": page,
        "meta": {
            "total": len([tr for tr in trades if isinstance(tr, dict) and _match(tr)]),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }

def get_auth_session(api_key, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0549000" if __import__("os").path.isdir("./environment_mix/0549000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, rpc_error=None, rpc_params=None, account_id=None):
        logs = _load("rpc_requests.json")
        logs.append({
            "id": "rpc_" + secrets.token_hex(12),
            "tool_name": "get-token-info",  # enum restriction; log under allowed tool while indicating actual in method
            "account_id": account_id,
            "token_id": None,
            "trade_id": None,
            "rpc_method": "local.get-auth-session",
            "rpc_params": rpc_params if isinstance(rpc_params, dict) else None,
            "http_status": int(status) if status is not None else None,
            "rpc_error": rpc_error,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("rpc_requests.json", logs)

    # validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log(400, rpc_error={"code": "VALIDATION_ERROR", "message": "api_key must be a non-empty string."}, rpc_params={"api_key": "[invalid]"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    api_keys = _load("api_keys.json")
    accounts = _load("accounts.json")

    key_row = None
    # Authenticate against client-visible value OR id; never against hashes.
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if api_key == k.get("id") or api_key == k.get("api_key") or api_key == k.get("value") or api_key == k.get("key"):
                status = k.get("status", "active")
                if status not in ("active", None):
                    key_row = None
                    break
                key_row = k
                break

    # If no api_keys collection or not found, attempt to interpret api_key as an account selector (relaxed, as datastore may not have api_keys).
    acct = None
    if key_row is not None:
        acct_id = key_row.get("account_id") or key_row.get("subject_account_id")
        if acct_id:
            acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id), None)
    if acct is None:
        # fallback: allow api_key equal to account.id or account.key_source (to match audited args like "keys_folder")
        acct = next((a for a in accounts if isinstance(a, dict) and (a.get("id") == api_key or a.get("key_source") == api_key) and a.get("status") == "active"), None)
        if acct is None:
            # last resort: any active account (ambient auth context)
            acct = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)

    if acct is None:
        _log(401, rpc_error={"code": "UNAUTHORIZED", "message": "Missing or invalid credentials."}, rpc_params={"api_key": "[redacted]"})
        return _err("UNAUTHORIZED", "Missing or invalid credentials.")

    # Quota/rate-limit: not specified in schema; report basic usage from rpc_requests (count last 24h)
    rpc_requests = _load("rpc_requests.json")
    since = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
    used_24h = 0
    if isinstance(rpc_requests, list):
        for r in rpc_requests:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct.get("id"):
                continue
            ts = r.get("created_at")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                except ValueError:
                    continue
                if dt >= since:
                    used_24h += 1

    _log(200, rpc_error=None, rpc_params={"api_key": "[redacted]", "resolved_account_id": acct.get("id")}, account_id=acct.get("id"))

    return {
        "subject": {
            "type": "account",
            "account_id": acct.get("id"),
            "public_key": acct.get("public_key"),
            "status": acct.get("status"),
            "key_source": acct.get("key_source"),
            "label": acct.get("label"),
        },
        "scopes": ["read", "write"],
        "usage": {
            "requests_last_24h": used_24h
        },
        "credential": {
            "provided_api_key": True,
            "credential_id": key_row.get("id") if isinstance(key_row, dict) else None
        }
    }
